import {describe,it,expect} from 'vitest';
import fixtures from './fixtures/rmutl-2569.json';
import { thaiLunarDate } from '../lib/suriyayatra';
import { lannaCalendar } from '../lib/lannaCalendar';
import { wanSia } from '../lib/wanSia';
import { faTeeSaeng } from '../lib/faTeeSaeng';

describe('สุริยยาตร์เทียบตารางอิสระจาก มทร.ล้านนา พ.ศ.2569–2570',()=>{
 // These 450 expected values were extracted by PDF column positions, not
 // generated by the algorithm. Rows with missing PDF glyphs were excluded.
 for(const f of fixtures)it(`${f.iso} · หน้าไฟล์ ${f.page}`,()=>{
  const model=thaiLunarDate(f.iso);
  expect({month:(model.month+1)%12+1,lunarDay:model.lunarDay,phase:model.phase,occurrence:model.occurrence}).toEqual({month:f.month,lunarDay:f.lunarDay,phase:f.phase,occurrence:f.occurrence});
  expect(wanSia(f.iso).verdict).toBe(f.wanSia?'bad':'not-bad');
 });
});
describe('ขอบเขตและกรณีสำคัญ',()=>{
 it('เดือน 10 ก่อนเปลี่ยนเป็นเดือน 10 หลัง ไม่ใช่เดือน 11',()=>{
  const a=lannaCalendar('2026-07-14'),b=lannaCalendar('2026-07-15');
  if(a.status==='unverified'||b.status==='unverified')throw Error('missing calendar');
  expect(a.day).toMatchObject({month:10,monthOccurrence:'first',phase:'waning',lunarDay:15});
  expect(b.day).toMatchObject({month:10,monthOccurrence:'second',phase:'waxing',lunarDay:1});
 });
 it('ออกเดือน 10 หลังเข้าเดือน 11',()=>{const x=lannaCalendar('2026-08-14');if(x.status==='unverified')throw Error('missing');expect(x.day).toMatchObject({month:11,monthOccurrence:'normal',lunarDay:1});});
 it('เปลี่ยนจุลศักราชในวันพญาวัน 2569',()=>{expect(thaiLunarDate('2026-04-15').chulaSakarat).toBe(1387);expect(thaiLunarDate('2026-04-16').chulaSakarat).toBe(1388);});
 it.each(['1900-01-01','2200-12-31','2024-02-29','2000-02-29'])('รองรับวันขอบเขตและ leap day: %s',iso=>expect(wanSia(iso).verdict).not.toBe('pending'));
 it.each(['1899-12-31','2201-01-01','1900-02-29','2100-02-29','2026-02-30','invalid'])('ปฏิเสธ %s',iso=>expect(()=>thaiLunarDate(iso)).toThrow(RangeError));
 it('ครบทุกวันในช่วง 301 ปี ไม่มีการข้ามหรือซ้ำของค่ำ และมีผลวันเสีย',()=>{
  const errors:string[]=[];let count=0;let prev:ReturnType<typeof thaiLunarDate>|undefined;
  for(let t=Date.UTC(1900,0,1);t<Date.UTC(2201,0,1);t+=86400000){
   const iso=new Date(t).toISOString().slice(0,10),day=thaiLunarDate(iso);
   if(prev){
    const same=prev.month===day.month&&prev.occurrence===day.occurrence;
    const p=prev.lunarDay+(prev.phase==='waning'?15:0),n=day.lunarDay+(day.phase==='waning'?15:0);
    if((same&&n!==p+1)||(!same&&(n!==1||p<29||p>30)))errors.push(iso);
   }
   if(wanSia(iso).verdict==='pending')errors.push(iso+' pending');
   const fa=faTeeSaeng(iso);
   if(fa.verdict==='pending'||!Number.isInteger(fa.remainder)||fa.remainder!<0||fa.remainder!>8)errors.push(iso+' invalid fa remainder');
   prev=day;count++;
  }
  expect(count).toBe(109938);expect(errors).toEqual([]);
 },15000);
});
